// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The value of a subscription is its plan's unit amount times its
// quantity, and the change is judged by that value:
//   - An upgrade (a higher value) applies at once and is billed at once: an invoice credits the unused time on the old plan
//     and charges the remaining time on the new one, for the rest of the current period. The current period does not change.
//   - A downgrade (a lower value) is pending: it takes effect at the next renewal, which bills the new plan and quantity.
//   - Any other change applies at once and bills nothing.
//
// A trialing subscription changes at once and bills nothing. Both plans must have the same currency and interval, and neither
// may be metered (ErrIncompatiblePlan).
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	cur, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if cur.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	from, ok := s.Store.Plan(orgID, cur.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	to := from
	if in.PlanID != nil {
		to, _ = s.Store.Plan(orgID, *in.PlanID)
	}
	qty := cur.Quantity
	if in.Quantity != nil {
		qty = *in.Quantity
	}
	if qty <= 0 {
		return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
	}
	if !compatible(from, to) {
		return store.Subscription{}, ErrIncompatiblePlan
	}

	oldValue, newValue := from.UnitAmount*int64(cur.Quantity), to.UnitAmount*int64(qty)
	trialing := cur.Status == store.Trialing
	downgrade := !trialing && newValue < oldValue
	upgrade := !trialing && newValue > oldValue
	now := s.Clock.Now()
	var lines []store.Line
	if upgrade {
		lines = prorationLines(from, to, oldValue, newValue, cur, now)
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(x *store.Subscription) error {
		if x.Status == store.Canceled {
			return ErrCanceled
		}
		if downgrade {
			planID := to.ID
			x.PendingPlanID, x.PendingQuantity = &planID, &qty
			return nil
		}
		x.PlanID, x.Quantity = to.ID, qty
		x.PendingPlanID, x.PendingQuantity = nil, nil
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	if !upgrade {
		return sub, nil
	}
	paid, err := s.invoice(ctx, sub, to.Currency, lines, now, sub.CurrentPeriodEnd)
	if err != nil {
		return sub, err
	}
	if !paid {
		return s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, nil
}

