// setupPlans returns an environment with a customer (charged to paymentMethod, if set) and two monthly licensed plans: Team at
// $20.00 and Pro at $50.00.
func setupPlans(t *testing.T, paymentMethod string) (*apitest.Env, store.Customer, store.Plan, store.Plan) {
	t.Helper()
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	if paymentMethod != "" {
		_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = paymentMethod; return nil })
	}
	return e, c, e.CreatePlan(e.Acme, "Team", "USD", "20.00"), e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
}

func subscribe(t *testing.T, e *apitest.Env, c store.Customer, p store.Plan, qty int) store.Subscription {
	t.Helper()
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: qty})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

// lastThird moves the clock so that a third of the subscription's current period is left.
func lastThird(e *apitest.Env, sub store.Subscription) {
	e.Clock.Set(sub.CurrentPeriodEnd.Add(-sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / 3))
}

// prorationInvoice returns the subscription's invoice with two lines, which is the invoice of an upgrade.
func prorationInvoice(t *testing.T, e *apitest.Env, sub store.Subscription) store.Invoice {
	t.Helper()
	for _, inv := range e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
		if len(inv.Lines) == 2 {
			return inv
		}
	}
	t.Fatal("no proration invoice")
	return store.Invoice{}
}

func TestUpgradeBillsTheRemainingTimeAtOnce(t *testing.T) {
	e, c, team, pro := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, team, 1)
	lastThird(e, sub)
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != pro.ID || got.PendingPlanID != nil || got.PendingQuantity != nil ||
		!got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("upgraded = %+v (the period does not change)", got)
	}
	inv := prorationInvoice(t, e, sub)
	// A third of the period is left: 2000 of 3 is 667 and 5000 of 3 is 1667, each rounded.
	want := []store.Line{
		{Description: "Unused time on Team", Quantity: 1, UnitAmount: -667},
		{Description: "Remaining time on Pro", Quantity: 1, UnitAmount: 1667},
	}
	if inv.Status != store.InvoicePaid || !slices.Equal(inv.Lines, want) {
		t.Fatalf("invoice = %+v", inv)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 1000 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeInvoiceCarriesDiscountAndTax(t *testing.T) {
	e, c, team, pro := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, team, 1)
	_, _ = e.Store.UpdateSubscription(e.Acme.ID, sub.ID, func(x *store.Subscription) error { x.DiscountPercent = 10; return nil })
	_, _ = e.Store.UpdateOrg(e.Acme.ID, func(o *store.Org) error { o.TaxRateBP = 2000; return nil })
	lastThird(e, sub)
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID}); err != nil {
		t.Fatal(err)
	}
	inv := prorationInvoice(t, e, sub)
	// The lines come to 1000; a 10% discount leaves 900, and 20% tax on that is 180.
	if inv.DiscountPercent != 10 || inv.TaxRateBP != 2000 || billing.Compute(inv).Total != 1080 || inv.Status != store.InvoicePaid {
		t.Fatalf("invoice = %+v, totals %+v", inv, billing.Compute(inv))
	}
}

func TestUpgradeWithoutPaymentMethodStaysOpen(t *testing.T) {
	e, c, team, pro := setupPlans(t, "")
	ctx := context.Background()
	sub := subscribe(t, e, c, team, 1)
	lastThird(e, sub)
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil || got.PlanID != pro.ID || got.Status != store.Active {
		t.Fatalf("upgraded = %+v, %v", got, err)
	}
	if inv := prorationInvoice(t, e, sub); inv.Status != store.InvoiceOpen {
		t.Fatalf("invoice = %+v, want open", inv)
	}
}

func TestDeclinedUpgradeIsPastDueAndStillApplies(t *testing.T) {
	e, c, team, pro := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, team, 1)
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	lastThird(e, sub)
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil || got.PlanID != pro.ID || got.Status != store.PastDue {
		t.Fatalf("upgraded = %+v, %v", got, err)
	}
	inv := prorationInvoice(t, e, sub)
	if ps := e.Store.Payments(e.Acme.ID, inv.ID); inv.Status != store.InvoiceOpen || len(ps) != 1 || ps[0].Status != store.PaymentFailed {
		t.Fatalf("invoice = %+v, payments = %+v", inv, ps)
	}
}

func TestDowngradeTakesEffectAtTheNextRenewal(t *testing.T) {
	e, c, team, pro := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, pro, 1)
	lastThird(e, sub)
	// Pro x 1 is 5000; Team x 2 is 4000, so this is a downgrade.
	qty := 2
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID, Quantity: &qty})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != pro.ID || got.Quantity != 1 || got.Status != store.Active ||
		got.PendingPlanID == nil || *got.PendingPlanID != team.ID || got.PendingQuantity == nil || *got.PendingQuantity != 2 {
		t.Fatalf("downgraded = %+v", got)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("a downgrade was billed: %d invoices", len(invs))
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	renewed, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if renewed.PlanID != team.ID || renewed.Quantity != 2 || renewed.PendingPlanID != nil || renewed.PendingQuantity != nil || renewed.Status != store.Active {
		t.Fatalf("renewed = %+v", renewed)
	}
	for _, inv := range e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
		if inv.PeriodStart != nil && inv.PeriodStart.Equal(renewed.CurrentPeriodStart) {
			if len(inv.Lines) != 1 || inv.Lines[0].Quantity != 2 || inv.Lines[0].UnitAmount != 2000 || inv.Status != store.InvoicePaid {
				t.Fatalf("renewal invoice = %+v, want 2 x Team", inv)
			}
			return
		}
	}
	t.Fatal("no renewal invoice")
}

func TestPatchBackToTheCurrentValueClearsAPendingDowngrade(t *testing.T) {
	e, c, team, pro := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, pro, 1)
	lastThird(e, sub)
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID}); err != nil {
		t.Fatal(err)
	}
	qty := 1
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID, Quantity: &qty})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != pro.ID || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("patched back = %+v", got)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("a change of the same value was billed: %d invoices", len(invs))
	}
}

func TestUpgradeClearsAPendingDowngrade(t *testing.T) {
	e, c, team, pro := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, pro, 1)
	lastThird(e, sub)
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID}); err != nil {
		t.Fatal(err)
	}
