}

func TestSameValueAppliesWithoutBilling(t *testing.T) {
	e, c, team, _ := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, team, 2) // 2 x 2000
	big := e.CreatePlan(e.Acme, "Team Plus", "USD", "40.00")
