func TestUpgradeBillsTheRemainingTimeAtOnce(t *testing.T) {
	e, c, team, pro := setupPlans(t, "pm_card_visa")
	ctx := context.Background()
	sub := subscribe(t, e, c, team, 1)
	lastThird(e, sub)
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != pro.ID || got.PendingPlanID != nil || got.PendingQuantity != nil ||
		!got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("upgraded = %+v (the period does not change)", got)
	}
	inv := prorationInvoice(t, e, sub)
	// A third of the period is left: 2000 of 3 is 667 and 5000 of 3 is 1667, each rounded.
	want := []store.Line{
		{Description: "Unused time on Team", Quantity: 1, UnitAmount: -667},
		{Description: "Remaining time on Pro", Quantity: 1, UnitAmount: 1667},
